// Access workflow-level static data
const data = $getWorkflowStaticData('global');

// 24 hours TTL
const TTL = 24 * 60 * 60 * 1000;

// Check cache validity
if (data.cachedValue && data.cachedValue[$input.first().json.url] && data.cachedValue[$input.first().json.url].timestamp && 
    (Date.now() - data.cachedValue[$input.first().json.url].timestamp) < TTL) {
	return [{ json: { fromCache: true, data: data.cachedValue[$input.first().json.url].value, timestamp:  data.cachedValue[$input.first().json.url].timestamp},  }];
}

// Return null if cache is missing or expired
return [{ json: { fromCache: false, data: null, timestamp: null } }];

var staticData = $getWorkflowStaticData('global');

staticData.cachedValue = staticData.cachedValue || {};
staticData.cachedValue[$('When Executed by Another Workflow').first().json.url] = {
  value: $input.first().json.output.text,
  timestamp: Date.now()
};

// Return null if cache is missing or expired
return [staticData.cachedValue[$('When Executed by Another Workflow').first().json.url]];
